(()=>{'use strict';const lines=[...document.querySelectorAll('.math-line')];function fit(el){const over=el.scrollWidth>el.clientWidth+2;if(over){el.tabIndex=0;el.dataset.scrollable='true';el.setAttribute('aria-label','可横向滚动的数学公式');}else{el.removeAttribute('tabindex');el.removeAttribute('data-scrollable');el.removeAttribute('aria-label');}const group=el.closest('.typeset-math');if(group){let note=group.querySelector('.math-scroll-note');if([...group.querySelectorAll('.math-line')].some(e=>e.hasAttribute('data-scrollable'))){if(!note){note=document.createElement('p');note.className='math-scroll-note';note.textContent='较长公式可横向滚动，或聚焦后使用方向键。';group.append(note);}}else note?.remove();}}
if('ResizeObserver'in window){const obs=new ResizeObserver(entries=>entries.forEach(e=>fit(e.target)));lines.forEach(e=>obs.observe(e));}document.fonts?.ready.then(()=>lines.forEach(fit));document.addEventListener('toggle',()=>lines.forEach(fit),true);window.addEventListener('resize',()=>lines.forEach(fit));lines.forEach(fit);
})();
